class C{String s(boolean p,String[]g){var s=String.join(".",g);int w=g[0].length()+1,L=s.length(),q[]=new int[L],v[]=q.clone();long A=0;for(int i=0;i<L;i++){var h=s.charAt(i);if(h<48|h>57)continue;int b=i,n=0;for(;i<L&&(h=s.charAt(i))>47&h<58;i++)n=n*10+h-48;int o=0;for(int y=-w;y<=w;y+=w)for(int x=b-1;x<=i;x++){int z=x+y;if(z>=0&z<L){h=s.charAt(z);if((h<48|h>57)&h!=46)o=1;if(h==42)v[z]=q[z]++<1?n:v[z]*n;}}if(p&o>0)A+=n;i--;}if(!p)for(int i=q.length;i-->0;)if(q[i]==2)A+=v[i];return A+"";}}
